<style>
  .monitor-shell{--mon:#5b5cf6;--ink:#172033;--muted:#697386}.monitor-hero{border-radius:1.35rem;padding:1.5rem;color:#fff;background:linear-gradient(135deg,#4338ca,#6d5dfc 55%,#06b6d4);box-shadow:0 1rem 2rem rgba(67,56,202,.18)}.monitor-hero h4{color:#fff}.monitor-hero p{color:rgba(255,255,255,.82);max-width:780px}.monitor-card{border:1px solid #e8eaf2;border-radius:1.1rem;box-shadow:0 .45rem 1.25rem rgba(15,23,42,.05)}.monitor-metric{height:100%;padding:1.1rem;background:#fff;border:1px solid #e8eaf2;border-radius:1rem}.monitor-metric .value{font-size:1.65rem;font-weight:800;color:var(--ink)}.monitor-metric .label{color:var(--muted);font-size:.82rem}.monitor-icon{width:42px;height:42px;border-radius:.8rem;display:flex;align-items:center;justify-content:center;font-size:22px;background:#eeedff;color:var(--mon)}.monitor-alert{border:1px solid #e8eaf2;border-left:4px solid var(--mon);border-radius:.9rem;padding:1rem;background:#fff}.monitor-alert.danger{border-left-color:#ef4444}.monitor-alert.warning{border-left-color:#f59e0b}.monitor-alert.info{border-left-color:#06b6d4}.monitor-table th{font-size:.72rem;text-transform:uppercase;letter-spacing:.04em;color:#778092;background:#f8f9fc}.monitor-table td{vertical-align:middle}.monitor-empty{padding:3rem;text-align:center;color:var(--muted)}.status-pill{display:inline-flex;padding:.3rem .65rem;border-radius:99px;font-size:.73rem;font-weight:700;background:#f0f1f5}.status-pill.success{background:#dcfce7;color:#15803d}.status-pill.warning{background:#fef3c7;color:#a16207}.status-pill.danger{background:#fee2e2;color:#b91c1c}.status-pill.info{background:#cffafe;color:#0e7490}.filter-panel{padding:1rem;border-radius:1rem;background:#f8f9fc;border:1px solid #e8eaf2}@media(max-width:767px){.monitor-hero{padding:1.15rem}.monitor-table{font-size:.82rem}}
</style>
